<input type="hidden" id="acp-prop"
       name="properties[Couleur du cadre]"
       value="" disabled aria-hidden="true">

<script>
(function () {

  var TRIGGER  = 'Cadre Displate + Cadre';
  var CHOOSE   = '{{ acp_choose }}';

  var panel = document.getElementById('acp-panel');
  var prop  = document.getElementById('acp-prop');
  var err   = document.getElementById('acp-err');
  var valEl = document.getElementById('acp-val');

  /* ─────────────────────────────────────────────────────────
     getForm — même sélecteurs que le format selector
  ───────────────────────────────────────────────────────── */
  function getForm() {
    return (
      document.querySelector('.product-form form')        ||
      document.querySelector('form[action*="/cart/add"]') ||
      document.querySelector('product-form form')         ||
      document.querySelector('form.product-form')         ||
      document.querySelector('[data-product-form] form')
    );
  }

  /* ─────────────────────────────────────────────────────────
     attachProp : injecte l'input property dans le form.
     Appelé en boucle (setInterval) car Kalles peut re-rendre
     le form lors d'un changement de variante.
  ───────────────────────────────────────────────────────── */
  function attachProp() {
    var f = getForm();
    if (!f) return;
    if (f.contains(prop)) return; /* déjà attaché */
    var btn = f.querySelector('[name="add"],[data-add-to-cart],.btn-add-to-cart,.product-form__submit');
    if (btn) f.insertBefore(prop, btn);
    else f.appendChild(prop);
  }

  /* ─────────────────────────────────────────────────────────
     checkFormat : lit quelle carte .apx-card est active
     et affiche/masque le panel en conséquence.
     Appelé par le MutationObserver — pas de hook apxPick.
  ───────────────────────────────────────────────────────── */
  function checkFormat() {
    var active = document.querySelector('.apx-card.apx-on');
    var show   = !!(active && active.getAttribute('data-fmt') === TRIGGER);
    showPanel(show);
  }

  function showPanel(show) {
    panel.style.display = show ? 'block' : 'none';
    prop.disabled = !show;
    if (!show) {
      resetSwatches();
      err.style.display = 'none';
    }
  }

  /* ─────────────────────────────────────────────────────────
     acpPick : sélection d'une couleur de cadre
  ───────────────────────────────────────────────────────── */
  window.acpPick = function (card) {
    resetSwatches();
    card.classList.add('acp-on');
    card.setAttribute('aria-checked', 'true');
    var couleur = card.getAttribute('data-couleur');
    prop.value    = couleur;
    prop.disabled = false;
    if (valEl) valEl.textContent = couleur;
    err.style.display = 'none';
  };

  function resetSwatches() {
    document.querySelectorAll('.acp-swatch').forEach(function (s) {
      s.classList.remove('acp-on');
      s.setAttribute('aria-checked', 'false');
    });
    prop.value = '';
    if (valEl) valEl.textContent = CHOOSE;
  }

  /* ─────────────────────────────────────────────────────────
     Garde ATC : bloque l'ajout si cadre actif mais pas de couleur
  ───────────────────────────────────────────────────────── */
  function guardCart() {
    var f = getForm();
    if (!f) return;

    function blocked() {
      return panel.style.display !== 'none' && !prop.value;
    }
    function showErr() {
      err.style.display = 'block';
      panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }

    f.addEventListener('submit', function (e) {
      if (blocked()) {
        e.preventDefault(); e.stopImmediatePropagation();
        showErr(); return false;
      }
    }, true);

    function hookBtn() {
      var btn = f.querySelector(
        '[name="add"],[data-add-to-cart],.btn-add-to-cart,.product-form__submit,.js-add-to-cart'
      );
      if (btn && !btn.__acpG) {
        btn.__acpG = true;
        btn.addEventListener('click', function (e) {
          if (blocked()) {
            e.preventDefault(); e.stopImmediatePropagation();
            showErr();
          }
        }, true);
      }
    }
    hookBtn();
    new MutationObserver(hookBtn).observe(f, { childList: true, subtree: true });
  }

  /* ─────────────────────────────────────────────────────────
     watchFormatCards : MutationObserver sur le format selector.
     Détecte l'ajout/suppression de la classe "apx-on" sur
     les cartes .apx-card — sans aucun hook sur apxPick.
  ───────────────────────────────────────────────────────── */
  function watchFormatCards() {
    /* Observe le conteneur #apx-fmt (ou body en fallback) */
    var target = document.getElementById('apx-fmt') || document.body;

    new MutationObserver(function (mutations) {
      /* On ne ré-évalue que si une mutation concerne "class"
         sur un élément qui a la classe apx-card */
      for (var i = 0; i < mutations.length; i++) {
        var m = mutations[i];
        if (m.attributeName === 'class') {
          var el = m.target;
          if (el.classList && el.classList.contains('apx-card')) {
            checkFormat();
            return; /* une seule évaluation suffit */
          }
        }
      }
    }).observe(target, {
      attributes: true,
      attributeFilter: ['class'],
      subtree: true
    });
  }

  /* ─────────────────────────────────────────────────────────
     Init
  ───────────────────────────────────────────────────────── */
  function init() {
    attachProp();

    /* Re-injecter l'input si Kalles re-rend le form */
    setInterval(attachProp, 600);

    guardCart();
    watchFormatCards();

    /* État initial (ex : page chargée avec Displate+Cadre déjà actif) */
    checkFormat();
  }

  /* Lancer après le format selector (qui s'initialise à 180ms) */
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () {
      setTimeout(init, 220);
    });
  } else {
    setTimeout(init, 220);
  }

  /* Re-init si Shopify recharge la section (éditeur de thème) */
  document.addEventListener('shopify:section:load', function () {
    setTimeout(function () {
      attachProp(); watchFormatCards(); guardCart(); checkFormat();
    }, 300);
  });

}());
</script>

